def describe_infrastructure_era_intelligence() -> str:
    lines = [
        "TitanAI Advanced Intelligence Infrastructure Era",
        "",
        "This layer frames TitanAI as a large-scale intelligence operating layer for coordinating agents, knowledge, architecture, quality, deployment, monitoring, documentation, product, marketplace, and communication systems.",
        "",
    ]
    for capability in INFRASTRUCTURE_ERA_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
